export const mod=(e,t)=>(e%t+t)%t;export function assert(e,t="Assertion failed!"){if(!e)throw new Error(t)}export const deepFreeze=e=>{for(const t of Reflect.ownKeys(e)){const r=e[t];(r&&"object"==typeof r||"function"==typeof r)&&deepFreeze(r)}return Object.freeze(e)};export class InsertAssignment{value;constructor(e){this.value=e}}export class ArrayAssignments{value;constructor(e){this.value=e}}export const immutableDeepAssign=(e,t)=>{if(t instanceof ArrayAssignments){assert(Array.isArray(e),`Expected an array. Got ${typeof e}.`);const r=[...e],s=Object.keys(t.value).sort(((e,t)=>Number(t)-Number(e)));for(const e of s){const s=t.value[Number(e)];void 0===s?r.splice(Number(e),1):s instanceof InsertAssignment?r.splice(Number(e),0,s.value):r[Number(e)]=immutableDeepAssign(r[e],s)}return Object.freeze(r)}if("object"==typeof t&&!Array.isArray(t)){assert(!Array.isArray(e),"Expected an object. Got an array.");const r={...e},s=Object.keys(t);for(const e of s){const s=t[e];void 0===s?delete r[e]:r[e]=immutableDeepAssign(r[e],s)}return Object.freeze(r)}return t};